/// <reference types="svelte" />
/**
 * Reactive tick for Svelte components that read game.t() / uiText via legacy game.language.
 * Subscribe once; call trackGameLanguage() inside $derived to re-run on LANGUAGE_CHANGED.
 */

import { GameEventType as Evt } from '../bus/events.js';
import { useFacadeSubscription } from './useFacadeSubscription.ts';

export function useGameLanguageTick(): { trackGameLanguage: () => void } {
  let i18nGen = $state(0);

  useFacadeSubscription(Evt.LANGUAGE_CHANGED, () => {
    i18nGen += 1;
  });

  function trackGameLanguage(): void {
    void i18nGen;
  }

  return { trackGameLanguage };
}
